refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.6.0

     Ajout de error_mode,
     error_store et
     error_handler.

&reftitle.notes;
Ces options ne peuvent pas être définies avec stream_context_set_default, qui lance une ValueError si ces options sont passées.
Seules les erreurs de la couche de flux sont concernées. Les autres erreurs d'une fonction, comme une ValueError ou une TypeError pour un argument invalide, sont lancées comme d'habitude.

  &reftitle.examples;

   Lancer des exceptions pour les erreurs de flux


<?php
$context = stream_context_create([
    'stream' => [
        'error_mode' => StreamErrorMode::Exception,
    ],
]);

try {
    $stream = fopen('/nonexistent/file.txt', 'r', false, $context);
} catch (StreamException $exception) {
    echo $exception->getMessage(), PHP_EOL;

    foreach ($exception->getErrors() as $error) {
        echo $error->wrapperName, ': ', $error->code->name, PHP_EOL;
    }
}


   &example.outputs;


Failed to open stream: No such file or directory
plainfile: OpenFailed




   Récupérer les erreurs sans diagnostics


<?php
$context = stream_context_create([
    'stream' => [
        'error_mode' => StreamErrorMode::Silent,
    ],
]);

$stream = fopen('/nonexistent/file.txt', 'r', false, $context);
var_dump($stream);

foreach (stream_last_errors() as $error) {
    echo $error->code->name, ': ', $error->message, PHP_EOL;
}


   &example.outputs;


bool(false)
OpenFailed: Failed to open stream: No such file or directory




   Recevoir les erreurs dans un gestionnaire d'erreurs


<?php
$context = stream_context_create([
    'stream' => [
        'error_mode' => StreamErrorMode::Silent,
        'error_store' => StreamErrorStore::None,
        'error_handler' => function (array $errors): void {
            print_r($errors);
        },
    ],
]);

fopen('/nonexistent/file.txt', 'r', false, $context);


   &example.outputs;


Array
(
    [0] => StreamError Object
        (
            [code] => StreamErrorCode Enum
                (
                    [name] => OpenFailed
                )

            [message] => Failed to open stream: No such file or directory
            [wrapperName] => plainfile
            [severity] => 2
            [terminating] => 1
        )

)
